class NoiseConditionedDenoiser(nn.Module):
    def __init__(self, channels=1, width=64):
        super().__init__()
        self.net = nn.Sequential(
            nn.Conv2d(channels + 1, width, 3, padding=1), nn.ReLU(inplace=True),
            nn.Conv2d(width, width, 3, padding=1), nn.ReLU(inplace=True),
            nn.Conv2d(width, channels, 3, padding=1)
        )

    def forward(self, noisy, sigma):
        condition = sigma.reshape(-1, 1, 1, 1).expand(-1, 1, noisy.size(2), noisy.size(3))
        return self.net(torch.cat([noisy, condition], dim=1))

model = NoiseConditionedDenoiser()
noisy = torch.randn(4, 1, 28, 28)
sigma = torch.full((4,), 0.1)
prediction = model(noisy, sigma)
